<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>$title,'subtitle'=>'Keep asset information accurate for reliable availability monitoring.']) ?><section class="panel form-panel"><form method="post" action="<?= $equipment?site_url('equipment/'.$equipment['id']):site_url('equipment') ?>" class="form-grid"><?= csrf_field() ?><label>Asset Code <span>*</span><input name="asset_code" value="<?= esc(old('asset_code',$equipment['asset_code']??'')) ?>" required<?= form_invalid('asset_code') ?>><?= form_error('asset_code') ?></label><label>Equipment Name <span>*</span><input name="name" value="<?= esc(old('name',$equipment['name']??'')) ?>" required<?= form_invalid('name') ?>><?= form_error('name') ?></label><label>Category <span>*</span><select name="category_id" required<?= form_invalid('category_id') ?>><option value="">Select category</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)old('category_id',$equipment['category_id']??'')===(string)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach; ?></select><?= form_error('category_id') ?></label><label>Storage Location <span>*</span><select name="location_id" required<?= form_invalid('location_id') ?>><option value="">Select location</option><?php foreach($locations as $l): ?><option value="<?= $l['id'] ?>" <?= (string)old('location_id',$equipment['location_id']??'')===(string)$l['id']?'selected':'' ?>><?= esc($l['name']) ?></option><?php endforeach; ?></select><?= form_error('location_id') ?></label><label>Total Quantity <span>*</span><input type="number" min="0" name="total_quantity" value="<?= esc(old('total_quantity',$equipment['total_quantity']??0)) ?>" required<?= form_invalid('total_quantity') ?>><?= form_error('total_quantity') ?></label><label>Unit <span>*</span><input name="unit" value="<?= esc(old('unit',$equipment['unit']??'piece')) ?>" required<?= form_invalid('unit') ?>><?= form_error('unit') ?></label><label>Condition <span>*</span><select name="condition"<?= form_invalid('condition') ?>><?php foreach(config('BantayGamit')->conditions as $k=>$v): ?><option value="<?= esc($k) ?>" <?= old('condition',$equipment['condition']??'good')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><?= form_error('condition') ?></label><label>Status <span>*</span><select name="status"<?= form_invalid('status') ?>><?php foreach(array_intersect_key(config('BantayGamit')->equipmentStatuses,array_flip(['available','unavailable','maintenance'])) as $k=>$v): ?><option value="<?= esc($k) ?>" <?= old('status',$equipment['status']??'available')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><?= form_error('status') ?><small class="field-hint">Use Retire from the equipment details page when the asset should leave active inventory.</small></label><label>Acquired Date<input type="date" name="acquired_date" value="<?= esc(old('acquired_date',$equipment['acquired_date']??'')) ?>"<?= form_invalid('acquired_date') ?>><?= form_error('acquired_date') ?></label><label class="wide-field">Description<textarea name="description" rows="3"<?= form_invalid('description') ?>><?= esc(old('description',$equipment['description']??'')) ?></textarea><?= form_error('description') ?></label><label class="wide-field">Notes<textarea name="notes" rows="3"<?= form_invalid('notes') ?>><?= esc(old('notes',$equipment['notes']??'')) ?></textarea><?= form_error('notes') ?></label><div class="form-actions wide-field"><a class="btn" href="<?= site_url('equipment') ?>">Cancel</a><button class="btn primary" type="submit"><?= ui_icon('save') ?> Save Equipment</button></div></form></section><?= $this->endSection() ?>
